import type { ExtractPropTypes, PropType } from 'vue'

export interface PopoverContentProps {
    /** Popover 相对于触发器的显示位置 */
    side?: 'top' | 'right' | 'bottom' | 'left'
    /** Popover 沿触发器轴线的对齐方式 */
    align?: 'start' | 'center' | 'end'
    /** Popover 与触发器之间的间距 */
    sideOffset?: number
}

export const popoverProps = {
    /** 内容位置与偏移配置 */
    content: {
        type: Object as PropType<PopoverContentProps>,
        default: () => ({ side: 'bottom', align: 'center', sideOffset: 0 })
    },
    /** 是否显示箭头 */
    arrow: {
        type: Boolean,
        default: true
    },
    /** 是否将 Popover 渲染到指定的 DOM 节点 (对于 UniApp 意义不大，保留作 API 一致性) */
    portal: {
        type: [Boolean, String] as PropType<boolean | string>,
        default: false
    },
    /** 点击外部时是否关闭 Popover */
    dismissible: {
        type: Boolean,
        default: true
    },
    /** 受控显示状态 */
    open: {
        type: Boolean,
        default: false
    },
    /** 非受控默认显示状态 */
    defaultOpen: {
        type: Boolean,
        default: false
    },
    /** 是否显示遮罩层并捕获焦点 */
    modal: {
        type: Boolean,
        default: false
    },
    /** 延迟打开时间 (ms) - 适用于 hover 模式 */
    openDelay: {
        type: Number,
        default: 0
    },
    /** 延迟关闭时间 (ms) - 适用于 hover 模式，防止意外关闭 */
    closeDelay: {
        type: Number,
        default: 0
    },
    /** 额外的类名 */
    customClass: {
        type: [String, Object, Array] as PropType<any>,
        default: ''
    },
    /** UI 覆盖配置 */
    ui: {
        type: Object as PropType<any>,
        default: () => ({})
    },
    // 以下为针对 uni-app 扩展的特有属性
    /**
     * 是否禁用 popover
     */
    disabled: {
        type: Boolean,
        default: false
    },
    /**
     * 显示的内容，可以通过 prop 也可以通过 slot 传入
     */
    title: {
        type: [String, Object] as PropType<string | Record<string, any>[]>,
        default: ''
    },
    useContentSlot: {
        type: Boolean,
        default: true
    },
    displayMode: {
        type: String as PropType<'normal' | 'menu'>,
        default: 'normal'
    }
}

export type PopoverProps = ExtractPropTypes<typeof popoverProps>

export interface PopoverExpose {
    open: () => void
    close: () => void
}
